<template><div class="page-container"><div class="page-header"><h2>采购进项发票管理</h2><el-button type="primary" @click="openCreate">登记发票</el-button></div><el-alert title="待收票按有效账户付款流水计算；付款后第20天临期，第30天逾期。" type="info" :closable="false" /><el-row :gutter="12" class="summary"><el-col :span="8"><el-statistic title="应收票金额" :value="summary.receivable_amount||0" prefix="¥" /></el-col><el-col :span="8"><el-statistic title="未收票金额" :value="summary.unreceived_amount||0" prefix="¥" /></el-col><el-col :span="8"><el-statistic title="逾期未收" :value="summary.overdue_amount||0" prefix="¥" /></el-col></el-row><el-tabs><el-tab-pane label="待收票"><el-table :data="candidates" border stripe><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="settlement_no" label="结算单号"/><el-table-column prop="payment_time" label="付款时间" width="170"/><el-table-column label="未收票" width="120"><template #default="{row}">¥{{ row.remaining_amount }}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.warning_status==='overdue'?'danger':row.warning_status==='near_due'?'warning':'success'">{{row.warning_status==='overdue'?'逾期':row.warning_status==='near_due'?'临期':'正常'}}</el-tag></template></el-table-column></el-table></el-tab-pane><el-tab-pane label="已收发票"><el-table :data="invoices" border stripe><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="invoice_no" label="发票号码"/><el-table-column prop="invoice_date" label="开票日期"/><el-table-column prop="invoice_type" label="票种"/><el-table-column prop="total_amount" label="价税合计"/></el-table></el-tab-pane></el-tabs><el-dialog v-model="visible" title="登记进项发票" width="760px"><el-form :model="form" label-width="100px"><el-row :gutter="12"><el-col :span="12"><el-form-item label="销方税号"><el-input v-model="form.supplierTaxNo"/></el-form-item></el-col><el-col :span="12"><el-form-item label="发票代码"><el-input v-model="form.invoiceCode"/></el-form-item></el-col><el-col :span="12"><el-form-item label="发票号码"><el-input v-model="form.invoiceNo"/></el-form-item></el-col><el-col :span="12"><el-form-item label="开票日期"><el-date-picker v-model="form.invoiceDate" value-format="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="票种"><el-input v-model="form.invoiceType" placeholder="如：增值税专用发票"/></el-form-item></el-col><el-col :span="12"><el-form-item label="税率"><el-input-number v-model="form.taxRate" :min="0" :max="1" :step="0.01"/></el-form-item></el-col><el-col :span="8"><el-form-item label="不含税金额"><el-input-number v-model="form.amountWithoutTax" :min="0" :precision="2"/></el-form-item></el-col><el-col :span="8"><el-form-item label="税额"><el-input-number v-model="form.taxAmount" :min="0" :precision="2"/></el-form-item></el-col><el-col :span="8"><el-form-item label="价税合计"><el-input-number v-model="form.totalAmount" :min="0" :precision="2"/></el-form-item></el-col></el-row><el-divider>关联付款（勾选后填写本票分摊金额）</el-divider><el-table :data="candidates" @selection-change="select"><el-table-column type="selection"/><el-table-column prop="supplier_name" label="供应商"/><el-table-column prop="settlement_no" label="结算单"/><el-table-column prop="remaining_amount" label="可分摊"/><el-table-column label="本票分摊"><template #default="{row}"><el-input-number v-model="amounts[row.payment_id]" :disabled="!selected.some(x=>x.payment_id===row.payment_id)" :min="0" :max="row.remaining_amount" :precision="2"/></template></el-table-column></el-table></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存并计入已收票</el-button></template></el-dialog></div></template>
<script setup>import {ref,onMounted} from 'vue'; import {ElMessage} from 'element-plus'; import api from '../api'; const candidates=ref([]),invoices=ref([]),summary=ref({}),visible=ref(false),selected=ref([]),amounts=ref({}); const blank=()=>({supplierTaxNo:'',invoiceCode:'',invoiceNo:'',invoiceDate:'',invoiceType:'增值税专用发票',taxRate:0.13,amountWithoutTax:0,taxAmount:0,totalAmount:0}); const form=ref(blank()); const load=async()=>{const [a,b]=await Promise.all([api.getPurchaseInvoiceCandidates({status:'open'}),api.getPurchaseInvoices()]); candidates.value=a.data?.list||[];summary.value=a.data?.summary||{};invoices.value=b.data?.list||[]}; const openCreate=()=>{form.value=blank();selected.value=[];amounts.value={};visible.value=true}; const select=v=>selected.value=v; const save=async()=>{try{await api.createPurchaseInvoice({...form.value,allocations:selected.value.map(r=>({paymentId:r.payment_id,settlementId:r.settlement_id,amount:amounts.value[r.payment_id]||0}))});ElMessage.success('已登记');visible.value=false;load()}catch(e){ElMessage.error(e.response?.data?.message||e.message)}};onMounted(load)</script><style scoped>.page-header{display:flex;justify-content:space-between;align-items:center}.summary{margin:16px 0}</style>
